import json, hashlib

CASES = [
    {"name":"[222,4^5] in Lambda/I_{5,4}","lower":[2,2,2,0,0],"upper":[4,4,4,4,4],"degrees":list(range(6,21)),"hDegrees":[1,2,3,4]},
    {"name":"[33,5^4] in Lambda/I_{4,5}","lower":[3,3,0,0],"upper":[5,5,5,5],"degrees":list(range(6,21)),"hDegrees":[1,2,3,4,5]}
]

def wt(p): return sum(p)
def contained(a,b): return all(x<=y for x,y in zip(a,b))
def partitions_between(lower, upper, degree):
    n=len(lower); out=[]
    def rec(i, prev, cur, total):
        if i==n:
            if total==degree: out.append(tuple(cur))
            return
        lo=lower[i]; hi=min(upper[i],prev,degree-total)
        for x in range(hi,lo-1,-1): rec(i+1,x,cur+[x],total+x)
    rec(0,upper[0],[],0)
    return out

def horizontal(lambda_, mu):
    if not contained(lambda_,mu): return False
    maxcol=max(mu) if mu else 0
    for c in range(1,maxcol+1):
        dl=sum(x>=c for x in lambda_)
        dm=sum(x>=c for x in mu)
        if dm-dl not in (0,1): return False
    return True

def smith_diagonal(M):
    A=[r[:] for r in M]
    m=len(A); n=len(A[0]) if m else 0
    k=0; ds=[]
    while k<m and k<n:
        pos=None
        for i in range(k,m):
            for j in range(k,n):
                if A[i][j]!=0 and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):
                    pos=(i,j)
        if pos is None: break
        i,j=pos; A[k],A[i]=A[i],A[k]
        for r in range(m): A[r][k],A[r][j]=A[r][j],A[r][k]
        while True:
            changed=True
            while changed:
                changed=False
                for i in range(k+1,m):
                    if A[i][k]:
                        q=A[i][k]//A[k][k]
                        A[i]=[A[i][c]-q*A[k][c] for c in range(n)]
                        if A[i][k]:
                            A[k],A[i]=A[i],A[k]
                        changed=True; break
                if changed: continue
                for j in range(k+1,n):
                    if A[k][j]:
                        q=A[k][j]//A[k][k]
                        for r in range(m): A[r][j]-=q*A[r][k]
                        if A[k][j]:
                            for r in range(m): A[r][k],A[r][j]=A[r][j],A[r][k]
                        changed=True; break
            bad=None
            p=A[k][k]
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j] % p:
                        bad=(i,j); break
                if bad: break
            if bad is None: break
            i,j=bad
            A[k]=[A[k][c]+A[i][c] for c in range(n)]
        if A[k][k]<0: A[k]=[-x for x in A[k]]
        ds.append(A[k][k]); k+=1
    return ds

def compute(case):
    lower=case['lower']; upper=case['upper']; hs=case['hDegrees']
    result={"name":case['name'],"lower":lower,"upper":upper,"degrees":case['degrees'],"hDegrees":hs,"degreeData":[]}
    for d in case['degrees']:
        cols=partitions_between(lower,upper,d)
        rows=[]; labels=[]
        for t in hs:
            for lam in partitions_between(lower,upper,d-t):
                row=[1 if horizontal(lam,mu) else 0 for mu in cols]
                rows.append(row); labels.append([t,list(lam)])
        diag=smith_diagonal(rows)
        rank=len(diag); free=len(cols)-rank
        torsion=[x for x in diag if x>1]
        result['degreeData'].append({"degree":d,"columns":[list(x) for x in cols],"rowLabels":labels,"matrix":rows,"shape":[len(rows),len(cols)],"smithNonzero":diag,"quotientFreeRank":free,"quotientTorsion":torsion})
    return result

out={"inputs":CASES,"cases":[compute(c) for c in CASES]}
a=[]; b=[]
for x,y in zip(out['cases'][0]['degreeData'],out['cases'][1]['degreeData']):
    a.append({"degree":x['degree'],"freeRank":x['quotientFreeRank'],"torsion":x['quotientTorsion']})
    b.append({"degree":y['degree'],"freeRank":y['quotientFreeRank'],"torsion":y['quotientTorsion']})
out['comparison']={"first":a,"second":b,"identicalDegreewise":a==b}
payload=json.dumps(out,sort_keys=True,separators=(',',':'))
print(payload)
print('STABLE_OUTPUT_SHA256='+hashlib.sha256(payload.encode()).hexdigest())
